            var mm = Math.round(sched.maxmart * fill);
            var revenue = base + mm;
            var lostSales = Math.round(baseDemand + sched.maxmart - revenue);
            var stockoutLost = lostShare > 0 ? Math.round(lostSales * Math.min(stockoutShare, lostShare) / lostShare) : 0;
            var derateLost = lostSales - stockoutLost;

            // purchase price: late payment costs up to 2% (case: about 1.4% at 55 days); prompt payment earns 1%
            var premiumRate = 0.02 * Math.max(0, 70 - ds.supplierRelationship) / 70;
            var cogsRate = 0.815 + premiumRate - (dpo <= 20 ? 0.01 : 0);
            var cogs = Math.round(revenue * cogsRate);
            var premium = Math.round(revenue * premiumRate);
            var grossProfit = revenue - cogs;

            // inventory: purchases restore the target stock on this month cost of sales
            var targetInventory = Math.round(cogs * dio / 30);
            var purchases = Math.max(0, cogs + targetInventory - ds.inventory);
            var newInventory = ds.inventory + purchases - cogs;

            // payables: each purchase is paid once, at the target the supplier still accepts
            var dpoAccepted = Math.round(20 + 0.6 * ds.supplierRelationship);
            var dpoEff = Math.min(dpo, dpoAccepted);
            var termsCut = dpo > dpoAccepted;
            var targetAP = Math.round(purchases * dpoEff / 30);
            var supplierPayments = Math.max(0, ds.accountsPayable + purchases - targetAP);
            var newAP = ds.accountsPayable + purchases - supplierPayments;

            // receivables and factoring (fee 3% of each invoice sold, stepping up past 40% of the book)
            var newDSO = Math.max(35, Math.min(62, 50 - 3 * (ce - 5)));
            var feeRate = 0.03 + 0.05 * Math.max(0, f - 0.4);
            var factoredBase = Math.round(base * f);
            var factoredMM = Math.round(mm * f);
            var factoredAmount = factoredBase + factoredMM;
            var factoringFee = Math.round(factoredAmount * feeRate);
            var factoringCash = factoredAmount - factoringFee;
            var keepBase = base - factoredBase;
            var targetAR = Math.round(sched.base * (1 - f) * newDSO / 30);
            var baseCollections = Math.max(0, ds.arBase + keepBase - targetAR);
            var newArBase = ds.arBase + keepBase - baseCollections;
            var q = (ds.mmQueue || [0, 0, 0, 0]).slice();
            var mmCollections = q[0];
            if (period === 4) { mmCollections = 0; q[1] += q[0]; }
            else if (period >= 5) { mmCollections = Math.round(q[0] * 0.5); q[1] += q[0] - mmCollections; }
            q.shift(); q.push(0); q[2] += mm - factoredMM;
            var collections = baseCollections + mmCollections;
            var newAR = newArBase + q[0] + q[1] + q[2] + q[3];

            // cash, revolver and overdraft
            var opex = 420;
            var carrying = Math.round(ds.inventory * 0.01);
            var creditLimit = this.CREDIT_LIMIT;
            var creditInterest = Math.round(ds.creditLineUsed * 0.015);
            var overdraftInterest = Math.round(Math.max(0, -ds.cash) * 0.04);
            var periodFinancingCost = factoringFee + creditInterest + overdraftInterest;
            var profit = grossProfit - opex - carrying - periodFinancingCost;
            var netCashFlow = collections + factoringCash - supplierPayments - opex - carrying - creditInterest - overdraftInterest;
            var newCash = ds.cash + netCashFlow;
            var newCreditUsed = ds.creditLineUsed, creditDraw = 0, creditRepay = 0;
            if (newCash < 200 && newCreditUsed < creditLimit) {
                creditDraw = Math.min(200 - newCash, creditLimit - newCreditUsed);
                newCash += creditDraw; newCreditUsed += creditDraw;
            }
            if (newCash > 1500 && newCreditUsed > 0) {
                creditRepay = Math.min(newCash - 1000, newCreditUsed);
                newCash -= creditRepay; newCreditUsed -= creditRepay;
            }
            newCash = Math.round(newCash);
            var distress = newCash < 0;

            // covenant: an overdraft is a liability, never an asset floored at zero
            var currentAssets = Math.max(0, newCash) + newAR + newInventory;
            var currentLiabilities = newAP + newCreditUsed + Math.max(0, -newCash);
            var currentRatio = currentLiabilities > 0 ? Math.round((currentAssets / currentLiabilities) * 100) / 100 : 9.99;
            var breach = currentRatio < this.COVENANT;

            var supplierDelta;
            if (dpo <= 30) supplierDelta = 1;
            else if (dpo <= 35) supplierDelta = 0;
            else if (dpo <= 40) supplierDelta = -1;
            else if (dpo <= 45) supplierDelta = -2;
            else if (dpo <= 50) supplierDelta = -4;
            else if (dpo <= 55) supplierDelta = -7;
            else supplierDelta = -10;
            if (distress) supplierDelta -= 4;
            var customerDelta = 0;
            if (ce >= 10) customerDelta = -4;
            else if (ce >= 9) customerDelta = -2;
            else if (ce >= 8) customerDelta = -1;
            else if (ce <= 3) customerDelta = 1;

            var headroom = newCash + creditLimit - newCreditUsed;

            ds.cash = newCash;
            ds.accountsReceivable = Math.round(newAR);
            ds.arBase = Math.round(newArBase);
            ds.mmQueue = q;
            ds.inventory = Math.round(newInventory);
            ds.accountsPayable = Math.round(newAP);
            ds.creditLineUsed = Math.round(newCreditUsed);
            ds.creditLineLimit = creditLimit;
            ds.creditAvailable = creditLimit - ds.creditLineUsed;
            ds.dso = Math.round(newDSO);
            ds.dio = Math.round(dio);
            ds.dpo = Math.round(dpoEff);
            ds.ccc = Math.round(dio + newDSO - dpoEff);
            ds.supplierRelationship = Math.max(0, Math.min(95, ds.supplierRelationship + supplierDelta));
            ds.customerRelationship = Math.max(0, Math.min(95, ds.customerRelationship + customerDelta));
            ds.currentRatio = currentRatio;
            ds.totalFinancingCost += periodFinancingCost;
            ds.totalRevenue += revenue;
            ds.totalProfit += profit;
            ds.distressMonths += distress ? 1 : 0;
            ds.breachMonths += breach ? 1 : 0;
            if (distress && !ds.firstDistress) ds.firstDistress = period;
            if (breach && !ds.firstBreach) ds.firstBreach = period;
            if (headroom < ds.minHeadroom) { ds.minHeadroom = Math.round(headroom); ds.minHeadroomMonth = period; }
            ds.factoredTotal += factoredAmount;
            ds.factoringFeesTotal += factoringFee;
            ds.supplierPremiumTotal += premium;
            ds.stockoutLostTotal += stockoutLost;
            ds.derateLostTotal += derateLost;
            ds.customerLostTotal += customerLost;
            ds.termsCutMonths += termsCut ? 1 : 0;
            ds.overdraftInterestTotal += overdraftInterest;
            ds.decisionLog = (ds.decisionLog || []).concat([{ p: period, ce: ce, dpo: dpo, dio: dio, f: d.factoringPct }]);

            ds.cashHistory.push(ds.cash);
            ds.cccHistory.push(ds.ccc);
            ds.profitHistory.push(Math.round(profit));
            ds.revenueHistory.push(revenue);
            ds.financingCostHistory.push(periodFinancingCost);
            ds.ratioSum = (ds.ratioSum || 0) + currentRatio;
            ds.supplierRelSum = (ds.supplierRelSum || 0) + ds.supplierRelationship;
            ds.customerRelSum = (ds.customerRelSum || 0) + ds.customerRelationship;

            var sc = this._composite(ds, period);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: sc.total, liquidity: sc.L, profitability: sc.P, covenant: sc.C, relationships: sc.R });
            ds.performanceTier = this._tier(sc.total);

            return {
                period: period,
                revenue: revenue,
                cogs: cogs,
                grossProfit: grossProfit,
                profit: Math.round(profit),
                collections: collections,
                maxmartCollections: mmCollections,
                factoringCash: factoringCash,
                factoringFee: factoringFee,
                supplierPayments: supplierPayments,
                purchases: purchases,
                opex: opex + carrying,
                creditInterest: creditInterest + overdraftInterest,
                creditDraw: Math.round(creditDraw),
                creditRepay: Math.round(creditRepay),
                financingCost: periodFinancingCost,
                netCashFlow: Math.round(netCashFlow),
                cash: ds.cash,
                ccc: ds.ccc,
                dso: ds.dso,
                dio: ds.dio,
                dpo: ds.dpo,
                dpoRequested: dpo,
                currentRatio: currentRatio,
                supplierRelationship: ds.supplierRelationship,
                customerRelationship: ds.customerRelationship,
                fillRate: Math.round(fill * 100),
                lostSales: lostSales,
                creditAvailable: ds.creditAvailable,
                headroom: Math.round(headroom),
                distress: distress,
                covenantBreach: breach,
                termsCut: termsCut,
                overallScore: sc.total,
                score: sc.total,
                performanceTier: ds.performanceTier
            };
        }

        _composite(ds, period) {
            var n = Math.max(1, period || 1);
            var L = Math.max(0, 100 - 22 * (ds.distressMonths || 0)) * (0.3 + 0.7 * Math.max(0, Math.min(1, (ds.minHeadroom === 99999 ? 3500 : ds.minHeadroom) / 3500)));
            var P = Math.max(0, Math.min(100, (ds.totalProfit / n - 200) / 250 * 100));
            var C = 100 * (1 - (ds.breachMonths || 0) / n);
            var R = (ds.supplierRelationship + ds.customerRelationship) / 2;
            var total = Math.round(Math.max(0, Math.min(100, 0.35 * L + 0.45 * P + 0.1 * C + 0.1 * R)));
            return { total: total, L: Math.round(L), P: Math.round(P), C: Math.round(C), R: Math.round(R) };
        }

        _tier(score) {
            for (var i = 0; i < this.TIERS.length; i++) { if (score >= this.TIERS[i].min) return this.TIERS[i].id; }
            return 'beginner';
        }

        _lang() {
            var l = '';
            try { if (window.vcI18n && window.vcI18n._lang) l = window.vcI18n._lang; } catch (e) {}
            if (!l) l = document.documentElement.lang || 'en';
            return String(l).toLowerCase().slice(0, 2) === 'es' ? 'es' : 'en';
        }

        _t(key, vars) {
            var sim = window.mySimulation;
            var out = sim && typeof sim.t === 'function' ? sim.t(key, vars) : key;
            if (out === key) {
                var tr = this.getTranslations();
                out = (tr[this._lang()] && tr[this._lang()][key]) || tr.en[key] || key;
                if (vars) out = String(out).replace(/\{(\w+)\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; });
            }
            return out;
        }

        _n(v) {
            return Math.round(v).toLocaleString(this._lang() === 'es' ? 'es-MX' : 'en-US');
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return '$' + self._n(v); });
            uiManager.bind('cccDisplay', 'domainState.ccc', function(v) { return v + ' d'; });
            uiManager.bind('creditDisplay', 'domainState.creditAvailable', function(v) { return '$' + self._n(v); });
            uiManager.bind('ratioDisplay', 'domainState.currentRatio', function(v) { return Number(v).toFixed(2) + 'x'; });
            uiManager.bind('supplierDisplay', 'domainState.supplierRelationship', function(v) { return v + '/100'; });
            uiManager.bind('customerDisplay', 'domainState.customerRelationship', function(v) { return v + '/100'; });
            uiManager.bind('dsoDisplay', 'domainState.dso');
            uiManager.bind('dioDisplay', 'domainState.dio');
            uiManager.bind('dpoDisplay', 'domainState.dpo');
            uiManager.bind('cccCalcDisplay', 'domainState.ccc');
            this._bindPanels();
        }

        _bindPanels() {
            var self = this;
            if (this._panelsBound) return;
            this._panelsBound = true;
            var later = function () { setTimeout(function () { try { self._renderPanels(); } catch (e) {} }, 30); };
            document.addEventListener('express:langchanged', later);
            var hook = function () {
                var sim = window.mySimulation;
                if (!sim || !sim.eventBus || sim.__creceHooked) return;
                sim.__creceHooked = true;
                ['period:submitted', 'period:undone', 'language:changed', 'state:loaded', 'state:imported', 'simulation:reset', 'framework:initialized'].forEach(function (ev) {
                    try { sim.eventBus.on(ev, later); } catch (e) {}
                });
            };
            hook();
            setTimeout(function () { hook(); later(); }, 0);
        }

        _renderPanels() {
            var sim = window.mySimulation, state = sim && sim.state;
            if (!state) return;
            var self = this, t = function (k, v) { return self._t(k, v); }, N = function (v) { return self._n(v || 0); };
            var hist = state.history || [], n = hist.length, max = state.maxPeriods || 12;
            var last = n ? (hist[n - 1].results || {}) : null;
            var note = document.getElementById('creceMonthNote');
            if (note) {
                var m = Math.min(n + 1, max), key;
                if (n >= max) key = 'note_end';
                else key = 'note_' + m;
                note.textContent = t(key, { m: m });
            }
            var br = document.getElementById('creceBridge');
            if (br) {
                if (!last) { br.hidden = true; br.innerHTML = ''; }
                else {
                    var row = function (k, v, cls) { return '<tr' + (cls ? ' class="' + cls + '"' : '') + '><th scope="row">' + t(k) + '</th><td>' + (v < 0 ? '−$' + N(-v) : '$' + N(v)) + '</td></tr>'; };
                    br.hidden = false;
                    br.innerHTML = '<h4 class="crece-bridge-title">' + t('br_title', { m: last.period }) + '</h4>' +
                        '<table class="crece-bridge-table"><tbody>' +
                        row('br_coll', last.collections) +
                        row('br_fact', last.factoringCash) +
                        row('br_sup', -last.supplierPayments) +
                        row('br_opex', -last.opex) +
                        row('br_int', -last.creditInterest) +
                        row('br_net', last.netCashFlow, 'crece-bridge-total') +
                        row('br_credit', (last.creditDraw || 0) - (last.creditRepay || 0)) +
                        row('br_profit', last.profit, 'crece-bridge-profit') +
                        '</tbody></table>' +
                        '<p class="crece-bridge-note">' + t('br_note', { lost: N(last.lostSales), dpo: last.dpo, req: last.dpoRequested }) + '</p>';
                }
            }
            var ds = state.domainState || {};
            var cash = document.getElementById('cashChart');
            if (cash) {
                cash.setAttribute('role', 'img');
                cash.setAttribute('aria-label', t('chart_cash_alt', { v: (ds.cashHistory || []).map(function (v, i) { return 'M' + (i + 1) + ' ' + N(v); }).join(', ') || '—' }));
            }
            var ccc = document.getElementById('cccChart');
            if (ccc) {
                ccc.setAttribute('role', 'img');
                ccc.setAttribute('aria-label', t('chart_ccc_alt', { v: (ds.cccHistory || []).map(function (v, i) { return 'M' + (i + 1) + ' ' + v; }).join(', ') || '—' }));
            }
            var deb = document.getElementById('creceDebrief');
            if (deb) {
                if (n >= max) { deb.hidden = false; deb.innerHTML = this.formatCompletionMessage(this.getPerformanceSummary(hist)); }
                else { deb.hidden = true; deb.innerHTML = ''; }
            }
        }

