        getHint(state, results) {
            if (!results) return null;
            var t = function (k, v) { return window.mySimulation.t(k, v); };
            if (results.distress) return t('hint_cash_negative');
            if (results.termsCut) return t('hint_terms_cut', { days: results.dpo });
            if (results.period === 4 && results.maxmartCollections === 0) return t('hint_maxmart_late');
            if (results.headroom < 1000) return t('hint_cash_low');
            if (results.lostSales > 150) return t('hint_lost_sales', { lost: results.lostSales });
            if (results.currentRatio < 1.15) return t('hint_covenant');
            if (results.supplierRelationship < 50) return t('hint_supplier_risk');
            if (state.decisions.factoringPct > 50) return t('hint_factoring_expensive');
            if (results.profit > 0 && results.netCashFlow < 0) return t('hint_profit_not_cash', { profit: results.profit, flow: results.netCashFlow });
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.revenue', label: 'Revenue', i18nKey: 'col_revenue', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.netCashFlow', label: 'Net cash flow', i18nKey: 'col_ncf', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.cash', label: 'Cash', i18nKey: 'col_cash', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.ccc', label: 'CCC', i18nKey: 'col_ccc', formatter: function(v) { return v + 'd'; } },
                { key: 'results.financingCost', label: 'Financing Cost', i18nKey: 'col_financing', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.currentRatio', label: 'Current Ratio', i18nKey: 'col_ratio', formatter: function(v) { return Number(v).toFixed(2) + 'x'; } }
            ];
        }

        _finalDomain(history) {
            var sim = window.mySimulation;
            if (sim && sim.state && sim.state.domainState && sim.state.domainState.decisionLog && sim.state.domainState.decisionLog.length === history.length) {
                return sim.state.domainState;
            }
            // rebuild from the results log when the live state is not the one summarised
            var ds = this._freshState(), last = history[history.length - 1].results || {};
            ds.cash = last.cash; ds.supplierRelationship = last.supplierRelationship; ds.customerRelationship = last.customerRelationship;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {}, dd = history[i].decisions || {};
                ds.totalProfit += r.profit || 0;
                ds.totalFinancingCost += r.financingCost || 0;
                if (r.distress) { ds.distressMonths++; if (!ds.firstDistress) ds.firstDistress = r.period; }
                if (r.covenantBreach) { ds.breachMonths++; if (!ds.firstBreach) ds.firstBreach = r.period; }
                if (r.headroom !== undefined && r.headroom < ds.minHeadroom) { ds.minHeadroom = r.headroom; ds.minHeadroomMonth = r.period; }
                ds.decisionLog.push({ p: r.period, ce: dd.collectionEffort, dpo: r.dpoRequested || dd.paymentDays, dio: r.dio || dd.inventoryDays, f: dd.factoringPct || 0 });
            }
            return ds;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var ds = this._finalDomain(history);
            var n = history.length;
            var sc = this._composite(ds, n);
            var tier = this._tier(sc.total);
            var log = ds.decisionLog || [];
            var avg = function (k, from, to) {
                var s = 0, c = 0;
                for (var i = 0; i < log.length; i++) { if (log[i].p >= from && log[i].p <= to) { s += Number(log[i][k]) || 0; c++; } }
                return c ? s / c : 0;
            };
            var self = this, N = function (v) { return self._n(v); };
            var ins = [];
            // run-specific insights: what this run actually did
            if (ds.distressMonths > 0) {
                ins.push({ key: 'ins_distress', vars: { m: ds.firstDistress, n: ds.distressMonths, od: N(ds.overdraftInterestTotal || 0) } });
            }
            if (ds.totalProfit > 0 && ds.distressMonths > 0) ins.push({ key: 'ins_profit_lied', vars: { profit: N(ds.totalProfit) } });
            if (avg('f', 1, 4) <= 25 && avg('dpo', 1, 4) <= 35 && avg('ce', 1, 4) <= 6 && ds.minHeadroom < 2500) {
                ins.push({ key: 'ins_waited', vars: { h: N(ds.minHeadroom), m: ds.minHeadroomMonth } });
            }
            if (avg('f', 1, n) >= 80) ins.push({ key: 'ins_factor_all', vars: { fees: N(ds.factoringFeesTotal || 0) } });
            if (avg('dpo', 1, n) >= 55 || ds.termsCutMonths >= 2) {
                ins.push({ key: 'ins_stretched', vars: { prem: N(ds.supplierPremiumTotal || 0), lost: N(ds.derateLostTotal || 0), cut: ds.termsCutMonths || 0 } });
            }
            if ((ds.stockoutLostTotal || 0) > 200) ins.push({ key: 'ins_stockout', vars: { lost: N(ds.stockoutLostTotal) } });
            if (avg('dio', 1, n) >= 35) ins.push({ key: 'ins_buffer', vars: { d: Math.round(avg('dio', 1, n)) } });
            if (avg('ce', 1, n) >= 9.5) ins.push({ key: 'ins_dunning', vars: { lost: N(ds.customerLostTotal || 0) } });
            if (ds.distressMonths === 0) ins.push({ key: 'ins_survived', vars: { h: N(ds.minHeadroom), m: ds.minHeadroomMonth } });
            if (ds.distressMonths === 0 && avg('f', 1, 4) >= 40 && avg('f', 5, n) <= avg('f', 1, 4) - 15) ins.push({ key: 'ins_retuned', vars: {} });
            if ((ds.factoringFeesTotal || 0) > 0 && avg('f', 1, n) < 80) ins.push({ key: 'ins_factoring_cost', vars: { fees: N(ds.factoringFeesTotal) } });
            if (ins.length < 3) ins.push({ key: 'ins_relationships', vars: { s: ds.supplierRelationship, c: ds.customerRelationship } });
            ins = ins.slice(0, 5);

            var turning;
            if (ds.firstDistress) turning = { key: 'tp_distress', vars: { m: ds.firstDistress } };
            else turning = { key: 'tp_tightest', vars: { m: ds.minHeadroomMonth, h: N(ds.minHeadroom) } };

            return {
                wcms: sc.total,
                composite: sc.total,
                overallScore: sc.total,
                totalScore: sc.total,
                score: sc.total,
                totalPeriods: n,
                finalCash: ds.cash,
                totalProfit: Math.round(ds.totalProfit),
                totalFinancingCost: Math.round(ds.totalFinancingCost),
                distressMonths: ds.distressMonths,
                breachMonths: ds.breachMonths,
                minHeadroom: ds.minHeadroom,
                supplierRelationship: ds.supplierRelationship,
                customerRelationship: ds.customerRelationship,
                parts: sc,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._t('tier_' + tier),
                turningPoint: this._t(turning.key, turning.vars),
                insights: ins.map(function (x) { return self._t(x.key, x.vars); }),
                _insightKeys: ins,
                _turningKey: turning
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this, t = function (k, v) { return self._t(k, v); }, N = function (v) { return self._n(v || 0); };
            var p = s.parts || { L: 0, P: 0, C: 0, R: 0 };
